// Capturamos el texto del mensaje de WhatsApp
const messageText = $json.messages[0].text.body;

// Extraemos la primera URL de Google Drive que encontremos en el texto
const driveUrlMatch =
  messageText.match(/https?:\/\/(www\.)?drive\.google\.com\/[^\s]+/);
const driveUrl = driveUrlMatch ? driveUrlMatch[0] : null;

return [{
  json: {
    extracted_drive_url: driveUrl,
    original_text: messageText
  }
}];

// 1. Datos del mensaje original de WhatsApp
const webhookData = $('WhatsApp Trigger').first().json;
const messageBody = webhookData.messages[0];

// Texto base enviado por el usuario
const baseText = messageBody?.text?.body || messageBody?.image?.caption || messageBody?.video?.caption || messageBody?.interactive?.button_reply?.title || "";
const senderPhone = messageBody?.from;

// 2. Extraer datos del nodo de Scraping si se ha ejecutado
let socialInfoText = "";

try {
  // Intentamos obtener la respuesta del nodo Media Scraper
  const scraperOutput = $('Media Scraper').first().json;

  if (scraperOutput && Object.keys(scraperOutput).length > 0) {
    // Convertimos la salida del scraper a string JSON formateado
    socialInfoText = typeof scraperOutput === 'object' 
      ? JSON.stringify(scraperOutput, null, 2) 
      : scraperOutput;
  }
} catch (e) {
  // Si la rama que se ejecutó no pasó por "Media Scraper", no hace nada y continúa
  socialInfoText = "";
}

// 3. Construir el chat_input final concatenado
let finalChatInput = baseText;

if (socialInfoText) {
  finalChatInput = `${baseText}\n\n---\nINFORMACIÓN EXTRAÍDA DE REDES SOCIALES:\n${socialInfoText}`;
} else if (!finalChatInput) {
  finalChatInput = $json.chat_input || "[Archivo multimedia recibido]";
}

// 4. Preservar binarios de las rutas de descarga (Drive / WhatsApp)
const binaryData = $binary?.data ? { data: $binary.data } : {};

const wamId = messageBody.id;
const contextWamId = messageBody.context?.id || '';

return [{
  json: {
    wamid: wamId,
    chat_input: finalChatInput,
    from: senderPhone,
    context_wamid: contextWamId
  },
  binary: binaryData,
}];

// 1. Datos del mensaje y binarios
const formatMessageNode = $('Format Message').first();
const messageData = formatMessageNode?.json || {};
const binaryData = formatMessageNode?.binary || {};

// 2. Datos del perfil del usuario en PostgreSQL
const userProfile = $('Get User Profile').first()?.json || {};

// Normalización estricta de booleanos
const surveyCompleted = Boolean(userProfile.survey_completed);
const weeklySubscription = Boolean(userProfile.weekly_tips);
const profileDescription = userProfile.description || "Perfil no iniciado.";

// 3. Procesamos las listas semanales de forma segura
let weeklyListsArray = [];
try {
  weeklyListsArray = $('Get Last Weekly Lists').all().map(item => {
    const createdAt = item.json?.created_at || new Date().toISOString();
    let content = item.json?.message.content || {};

    if (typeof content === 'string') {
      try {
        content = JSON.parse(content);
      } catch (e) {
        content = { raw_text: content };
      }
    }

    return {
      send_date: createdAt,
      ...content
    };
  });
} catch (e) {
  weeklyListsArray = [];
}

// 4. Inyección estructurada de estado en la Ficha
const formattedProfileStatus = 
  `${profileDescription}

  ---
  [ESTADO ACTUAL EN BASE DE DATOS]
  - Cuestionario completado (survey_finished): ${surveyCompleted}
  - Suscripción a ideas semanales (weekly_reports_opt_in): ${weeklySubscription}`;

const formattedWeeklyLists = weeklyListsArray.length > 0 
  ? JSON.stringify(weeklyListsArray, null, 2) 
  : "[]";

// 5. Carga de la plantilla del System Prompt
const promptsConfig = $('System Prompts Config').first()?.json || {};
const rawPrompt = surveyCompleted 
  ? (promptsConfig.conversation_prompt || "") 
  : (promptsConfig.interviewer_prompt || "");

// Reemplazo seguro mediante expresiones regulares globales (replaceAll safe)
const finalSystemPrompt = rawPrompt
  .replace(/\{\{PROFILE_DESCRIPTION\}\}/g, formattedProfileStatus)
  .replace(/\{\{WEEKLY_LISTS\}\}/g, formattedWeeklyLists);

// 6. Construcción del input enriquecido con contexto citado
const rawContextData = $("Get Message Context").first()?.json?.message || null;
const currentText = messageData.chat_input || "";

let finalChatInput = currentText;

if (rawContextData) {
  const formattedContextJson = typeof rawContextData === 'object'
    ? JSON.stringify(rawContextData, null, 2)
    : rawContextData;

  finalChatInput = 
    `[CONTEXTO DE REFERENCIA - MENSAJE AL QUE EL USUARIO ESTÁ RESPONDIENDO]
    El usuario ha utilizado la función "Responder" de WhatsApp sobre el siguiente mensaje/contenido anterior.
    Usarás este JSON únicamente como trasfondo contextual:

    \`\`\`json
    ${formattedContextJson}
    \`\`\`
    [FIN DEL CONTEXTO DE REFERENCIA]

    [MENSAJE ACTUAL DEL USUARIO]
    ${currentText}`;
}

// 7. Salida consolidada
return [{
  json: {
    chat_input: finalChatInput,
    from: messageData.from,
    user_profile: userProfile,
    weekly_lists: weeklyListsArray,
    system_prompt: finalSystemPrompt
  },
  binary: binaryData
}];

// Obtener el mensaje entrante de WhatsApp
const messageText = $json.message || "";

// Expresión regular para cualquier enlace de Instagram (perfil, post, reel, tv)
const instagramRegex = /https?:\/\/(?:www\.)?instagram\.com\/[a-zA-Z0-9_\-\.\/]+/i;

// Expresión regular para cualquier enlace de TikTok (perfil, vídeo, vm.tiktok, vt.tiktok)
const tiktokRegex = /https?:\/\/(?:www\.|vm\.|vt\.)?tiktok\.com\/[a-zA-Z0-9_\-\.\/@]+/i;

let platform = '';
let extractedUrl = null;
let actorName = null;
let apiEndpoint = null;

if (instagramRegex.test(messageText)) {
  platform = 'instagram';
  extractedUrl = messageText.match(instagramRegex)[0];
  actorName = 'apidojo/instagram-scraper';
  apiEndpoint = 'https://api.apify.com/v2/actors/apidojo~instagram-scraper/run-sync-get-dataset-items?token={}';
} else if (tiktokRegex.test(messageText)) {
  platform = 'tiktok';
  extractedUrl = messageText.match(tiktokRegex)[0];
  actorName = 'novi/tiktok-scraper-ultimate';
  apiEndpoint = 'https://api.apify.com/v2/actors/novi~tiktok-scraper-ultimate/run-sync-get-dataset-items?token={}';
}

// Estructura de entrada unificada para ambos actores de Apify
const apifyInput = extractedUrl ? {
  startUrls: [ extractedUrl ],
  maxItems: 1
} : null;

return [{
  json: {
    ...$json,
    platform: platform,         // 'instagram', 'tiktok' o 'none'
    extracted_url: extractedUrl,// URL limpia extraída del mensaje
    actor_name: actorName,      // Actor de Apify a invocar
    api_endpoint: apiEndpoint,
    apify_input: apifyInput      // Input idéntico para ambas APIs
  }
}];

