let agentOutput;
const rawOutput = $json.output || "";

try {
  agentOutput = typeof rawOutput === 'string' ? JSON.parse(rawOutput) : rawOutput;
} catch (e) {
  // Limpieza por si Gemini envolvió el JSON en ```json ... ```
  const cleanedText = rawOutput.replace(/```json|```/g, '').trim();
  try {
    agentOutput = JSON.parse(cleanedText);
  } catch (err) {
    // Fallback de emergencia si el LLM devolvió texto plano por error
    agentOutput = {
      whatsapp_message: rawOutput,
      profile_update: null
    };
  }
}

const userProfile = $('Get User Profile').first()?.json || {};
const profileUpdate = agentOutput.profile_update || null;

// Si profile_update trae datos, usamos los nuevos; si es null, preservamos exactamente los de PostgreSQL
const finalDescription = profileUpdate?.updated_profile_description || userProfile.description || "Perfil no iniciado.";
const finalSurveyFinished = profileUpdate?.survey_finished ?? userProfile.survey_completed ?? false;
const finalWeeklyTips = profileUpdate?.weekly_reports_opt_in ?? userProfile.weekly_tips ?? false;

const sessionId = $('Prepare Input').first().json.from;

return [{
  json: {
    from: sessionId,
    whatsapp_message: agentOutput.whatsapp_message || rawOutput,
    description: finalDescription,
    survey_completed: finalSurveyFinished,
    weekly_tips: finalWeeklyTips,
    has_profile_changes: profileUpdate !== null
  }
}];

// Capturamos los datos del item actual
const inputItem = $input.first().json;

// 1. Comprobamos si el nodo anterior ha registrado un error de n8n/Gemini
const hasError = inputItem.error !== undefined || $node["AI Agent"]?.error !== undefined;

let userReply = "";
let rawErrorDetails = "";

if (hasError) {
  // Extraemos el mensaje de error o la pila técnica si existen
  const errObject = inputItem.error || $node["AI Agent"]?.error;
  rawErrorDetails = typeof errObject === 'object' ? JSON.stringify(errObject) : String(errObject);

  // 2. Interpretación amigable según el tipo de error
  if (rawErrorDetails.includes("503") || rawErrorDetails.includes("high demand")) {
    userReply = "⚠️ *Servidor ocupado:* El modelo de IA de Google está experimentando una alta demanda temporal. Por favor, inténtalo de nuevo en unos segundos.";
  } else if (rawErrorDetails.includes("429") || rawErrorDetails.includes("Quota")) {
    userReply = "⏳ *Límite alcanzado:* Se ha superado la cuota temporal de consultas. Espera un par de minutos antes de enviar otro mensaje.";
  } else if (rawErrorDetails.includes("timeout") || rawErrorDetails.includes("ETIMEDOUT")) {
    userReply = "⏱️ *Tiempo de espera agotado:* La respuesta ha tardado más de lo esperado en procesarse. Por favor, vuelve a intentarlo.";
  } else {
    // Respuesta genérica para otros errores
    userReply = "❌ *Lo sentimos:* Ha ocurrido un inconveniente procesando tu solicitud en este momento. Por favor, vuelve a intentarlo más tarde.";
  }
} else {
  // 3. Si todo funcionó bien, obtenemos la respuesta normal del Agente
  userReply = inputItem.output || inputItem.text || inputItem.chat_output || "Respuesta procesada correctamente.";
}

const sessionId = $('Prepare Input').first().json.from;

return [{
  json: {
    ...$json,
    is_error: hasError,
    // Este campo es el que debes enviar en el nodo final de respuesta de WhatsApp
    whatsapp_message: userReply,
    from: sessionId,
    // Detalle técnico mantenido por si quieres registrarlo en base de datos o logs
    error_details: hasError ? rawErrorDetails : null
  }
}];

